    (function () {
      var root = document.getElementById('events');
      if (!root) { return; }
      var buttons = root.querySelectorAll('.ev-filter');
      var cards = root.querySelectorAll('.event-card');
      var status = document.getElementById('ev-status');

      function apply(filter) {
        var shown = 0;
        for (var i = 0; i < cards.length; i++) {
          var match = filter === 'all' || cards[i].getAttribute('data-category') === filter;
          if (match) { cards[i].removeAttribute('hidden'); shown++; }
          else { cards[i].setAttribute('hidden', ''); }
        }
        for (var j = 0; j < buttons.length; j++) {
          buttons[j].setAttribute('aria-pressed', buttons[j].getAttribute('data-filter') === filter ? 'true' : 'false');
        }
        if (status) {
          status.textContent = filter === 'all'
            ? 'Showing all ' + shown + ' events'
            : 'Showing ' + shown + ' ' + filter + ' events';
        }
      }

      for (var k = 0; k < buttons.length; k++) {
        buttons[k].addEventListener('click', function () {
          apply(this.getAttribute('data-filter'));
        });
      }
    })();
