  <script>
    (function () {
      var form = document.getElementById('reg-form');
      var box = document.getElementById('reg-confirm');
      if (!form || !box) { return; }

      var TO = 'spark2026@example.com';
      var fields = [
        { el: document.getElementById('reg-name'), err: document.getElementById('reg-name-err'), msg: 'Enter your name.' },
        { el: document.getElementById('reg-email'), err: document.getElementById('reg-email-err'), msg: 'Enter your email.', bad: 'Enter a valid email address.' },
        { el: document.getElementById('reg-college'), err: document.getElementById('reg-college-err'), msg: 'Enter your college.' },
        { el: document.getElementById('reg-event'), err: document.getElementById('reg-event-err'), msg: 'Choose an event.' }
      ];
      var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      function setError(f, text) {
        f.err.textContent = text;
        f.el.setAttribute('aria-invalid', text ? 'true' : 'false');
      }

      function check(f) {
        var v = f.el.value.trim();
        if (!v) { setError(f, f.msg); return false; }
        if (f.bad && !EMAIL_RE.test(v)) { setError(f, f.bad); return false; }
        setError(f, '');
        return true;
      }

      for (var i = 0; i < fields.length; i++) {
        (function (f) {
          var evt = f.el.tagName === 'SELECT' ? 'change' : 'input';
          f.el.addEventListener(evt, function () {
            if (f.el.getAttribute('aria-invalid') === 'true') { check(f); }
          });
        })(fields[i]);
      }

      function addPara(parent, text) {
        var p = document.createElement('p');
        p.textContent = text;
        parent.appendChild(p);
        return p;
      }

      form.addEventListener('submit', function (e) {
        e.preventDefault();
        var firstBad = null;
        for (var k = 0; k < fields.length; k++) {
          if (!check(fields[k]) && !firstBad) { firstBad = fields[k].el; }
        }
        if (firstBad) {
          box.setAttribute('hidden', '');
          firstBad.focus();
          return;
        }

        var name = fields[0].el.value.trim();
        var email = fields[1].el.value.trim();
        var college = fields[2].el.value.trim();
        var event = fields[3].el.value;

        var body = [
          'Spark 2026 registration',
          '',
          'Name: ' + name,
          'Email: ' + email,
          'College: ' + college,
          'Event: ' + event
        ].join('\r\n');
        var mailto = 'mailto:' + TO +
          '?subject=' + encodeURIComponent('Spark 2026 registration: ' + event) +
          '&body=' + encodeURIComponent(body);

        while (box.firstChild) { box.removeChild(box.firstChild); }
        var h = document.createElement('h3');
        h.className = 'reg-confirm-title';
        h.textContent = 'Almost done, ' + name;
        box.appendChild(h);
        addPara(box, 'Your registration for ' + event + ' is ready. Your mail app should open with your details addressed to ' + TO + '. Press send in that email to complete it.');
        var p2 = document.createElement('p');
        p2.appendChild(document.createTextNode('Nothing opened? '));
        var a = document.createElement('a');
        a.href = mailto;
        a.textContent = 'Open the email again';
        p2.appendChild(a);
        p2.appendChild(document.createTextNode(' or send your details to ' + TO + ' yourself.'));
        box.appendChild(p2);

        box.removeAttribute('hidden');
        box.focus();
        if (box.scrollIntoView) { box.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }

        try { window.location.href = mailto; } catch (err) { /* fallback link is shown above */ }
      });
    })();
  </script>
